typescript.code:
import * as tt from "thinkthen";

// keep the complaints: the zipper and the strap
const reviews = ["Arrived a day early. Thank you!",
    "The zipper broke the first time I used it.",
    "The strap snapped on day two."];
console.log(await tt.filter("Is this a complaint?",
    reviews));
// your own scale, 0 to 2. An outage is "Immediate."
const levels = ["Routine.", "Soon.", "Immediate."];
const urgency = { score: "How urgent is this?", levels };
console.log(await tt.score(urgency,
    "Checkout is down and nobody can pay."));

rust.code:
use thinkthen::{Engine, Question};
let tt = Engine::from_env()?;
let teams = ["billing", "shipping", "account"];
let owner = Question::choose("Which team owns this?",
    &teams)?.build()?;
let texts = ["My card was charged twice.",
    "The courier lost my parcel.",
    "I cannot reset my password."];
// the compiler makes you handle "not sure"
for text in texts {
    match tt.choose(&owner, text)? {
        Some(team) => println!("{team}: {text}"),
        None => println!("a person: {text}"),
    }
}

c.code:
#include <stdio.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* score takes the JSON door: a request in, JSON out */
const char *ask = "{\"score\": \"How urgent is this?\", "
    "\"levels\": [\"Routine.\", \"Soon.\", "
    "\"Immediate.\"], "
    "\"evidence\": \"Checkout is down for everyone.\"}";
char *out = thinkthen_call(tt, ask);

/* an outage lands near 2, "Immediate." */
puts(out ? out : thinkthen_error_message(tt));
thinkthen_free_string(out);
thinkthen_engine_free(tt);

duckdb.code:
LOAD './thinkthen.duckdb_extension';

CREATE TABLE tickets AS SELECT * FROM (VALUES
    (1, 'My parcel is a week late. Not okay.'),
    (2, 'Thanks for the quick help yesterday!'),
    (3, 'We are locked out of our account.'),
    (4, 'I was billed twice for one order.')
) t(id, body);

-- the thank-you is no complaint, so it drops out
SELECT id, thinkthen_choose('Which team owns this?',
    body, ['billing', 'shipping', 'account']) AS team
FROM tickets
WHERE thinkthen_decide('Is this a complaint?', body);

